package com.hrflow.entity; import jakarta.persistence.*;import lombok.*;import java.time.*; @Entity @Getter @Setter @NoArgsConstructor @Table(name="leave_requests") public class LeaveRequest { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; Long employeeId,leaveTypeId; LocalDate startDate,endDate; String reason,attachmentPath; @Enumerated(EnumType.STRING) LeaveStatus status=LeaveStatus.PENDING; String reviewerComment; Instant createdAt=Instant.now(); Instant reviewedAt; }
